<script>
    /*
    |--------------------------------------------------------------------------
    | Load AI Suggestions
    |--------------------------------------------------------------------------
    */

    function loadAISuggestions(type, clicked = null) {

        let conversationId = $('#conversation-id').val();

        // Prevent duplicate request
        if (clicked && clicked.data('loading')) {
            return;
        }

        if (clicked) {
            clicked.data('loading', true);
            clicked.addClass('ai-suggestion-loading');
        }

        $.ajax({

            url: "{{ route('ai.assistant.suggestion') }}",

            type: "POST",

            data: {
                _token: "{{ csrf_token() }}",
                type: type,
                conversation_id: conversationId
            },

            success: function(response) {

                console.log('AI Suggestion:', response);

                if (response.success) {

                    appendAISuggestions(
                        response.type,
                        response.suggestions
                    );

                } else {

                    console.log(
                        response.message || 'Unable to generate suggestions.'
                    );
                }
            },

            error: function(xhr) {

                console.log('AI Suggestion Error:', xhr.responseJSON);

                let message =
                    xhr.responseJSON?.message ||
                    'Unable to generate AI suggestion.';

                console.log(message);
            },

            complete: function() {

                if (clicked) {

                    clicked.data('loading', false);

                    clicked.removeClass('ai-suggestion-loading');
                }
            }
        });
    }


    /*
    |--------------------------------------------------------------------------
    | Suggestion Tab Click
    |--------------------------------------------------------------------------
    */

    $(document).on('click', '[data-ai-suggestion]', function(e) {

        /*
         * Do NOT prevent Bootstrap tab switching.
         * Bootstrap needs the click event.
         */

        let clicked = $(this);

        let type = clicked.data('ai-suggestion');

        loadAISuggestions(type, clicked);

    });


    /*
    |--------------------------------------------------------------------------
    | Append AI Suggestions
    |--------------------------------------------------------------------------
    */

    function appendAISuggestions(type, suggestions) {

        let listId = '';

        switch (type) {

            case 'budget':
                listId = '#budgetSuggestionList';
                break;

            case 'requirements':
                listId = '#requirementsSuggestionList';
                break;

            case 'milestones':
                listId = '#milestonesSuggestionList';
                break;

            case 'timeanddeadlines':
                listId = '#timelineSuggestionList';
                break;

            case 'revisions':
                listId = '#revisionSuggestionList';
                break;

            default:
                console.log('Unknown AI suggestion type:', type);
                return;
        }


        let list = $(listId);

        if (!list.length) {
            console.log('Suggestion list not found:', listId);
            return;
        }


        /*
        * Remove old suggestions
        */

        list.empty();


        /*
        * Make sure suggestions is an array
        */

        if (!Array.isArray(suggestions)) {
            console.log('Invalid suggestions:', suggestions);
            return;
        }


        /*
        * Append suggestions
        */

        suggestions.forEach(function(suggestion) {

            const message = suggestion.text || '';

            let $single = $(`
                <div class="single ai-suggestion-item">

                    <div class="text"></div>

                    <div class="icon ai-send-suggestion"
                        style="cursor:pointer;">

                        <svg xmlns="http://www.w3.org/2000/svg"
                            width="14"
                            height="13"
                            viewBox="0 0 14 13"
                            fill="none">

                            <path
                                d="M12.8819 7.51827C13.7967 7.08927 13.7967 5.78716 12.8814 5.35876L1.70059 0.117445C0.782487 -0.312633 -0.21886 0.525673 0.0419857 1.50506L1.14552 5.64357L5.82661 5.64345C6.03506 5.64706 6.23375 5.73241 6.37988 5.8811C6.526 6.02979 6.60788 6.22993 6.60788 6.43841C6.60787 6.64689 6.52598 6.84704 6.37985 6.99574C6.23371 7.14443 6.03502 7.22979 5.82657 7.23342L1.14548 7.23355L0.0422784 11.3727C-0.219183 12.3515 0.782679 13.1892 1.70024 12.7596L12.8819 7.51827Z"
                                fill="#00A148" />

                        </svg>

                    </div>

                </div>
            `);


            /*
            * Set text safely
            */

            $single
                .find('.text')
                .text(message);


            /*
            * Store suggestion data
            */

            $single
                .find('.ai-send-suggestion')
                .data('message', message)
                .data('is-best', suggestion.is_best || false)
                .data('option-number', suggestion.option_number || null);


            /*
            * Mark best suggestion
            */

            if (suggestion.is_best === true) {
                $single.addClass('best-suggestion');
            }


            /*
            * Add to list
            */

            list.append($single);

        });
    }


    /*
    |--------------------------------------------------------------------------
    | Click AI Suggested Message
    |--------------------------------------------------------------------------
    |
    | When user clicks the green send icon,
    | put the suggestion into your chat input.
    |
    */

    $(document).on('click', '.ai-send-suggestion', function(e) {

        e.preventDefault();

        let message = $(this).data('message');

        if (!message) {
            return;
        }


        console.log('Selected AI suggestion:', message);


        /*
         * CHANGE THIS ID if your actual chat input
         * has a different ID.
         */

        let input = $('#AIchatMessageInput');


        if (input.length) {

            input.val(message);

            input.trigger('input');

            input.focus();

        } else {

            console.log('AI chat input not found.');

        }

    });


    /*
    |--------------------------------------------------------------------------
    | Load Budget Suggestions By Default
    |--------------------------------------------------------------------------
    */

    $(document).ready(function() {

        loadAISuggestions('budget');

    });
</script>